function testAddSub() {
  // Test valid addition
  const m1 = new Matrix([[1, 2], [3, 4]]);
  const m2 = new Matrix([[5, 6], [7, 8]]);
  const sum = m1.add(m2);
  console.assert(sum.get(0, 0) === 6, "Addition failed");
  console.assert(sum.get(0, 1) === 8, "Addition failed");
  console.assert(sum.get(1, 0) === 10, "Addition failed");
  console.assert(sum.get(1, 1) === 12, "Addition failed");

  // Test valid subtraction
  const diff = m2.sub(m1);
  console.assert(diff.get(0, 0) === 4, "Subtraction failed");
  console.assert(diff.get(0, 1) === 4, "Subtraction failed");
  console.assert(diff.get(1, 0) === 4, "Subtraction failed");
  console.assert(diff.get(1, 1) === 4, "Subtraction failed");

  // Test that original matrices are unchanged
  console.assert(m1.get(0, 0) === 1, "Original matrix changed during addition");
  console.assert(m2.get(0, 0) === 5, "Original matrix changed during subtraction");

  // Test shape mismatch error for addition
  const m3 = new Matrix([[1, 2, 3], [4, 5, 6]]);
  try {
    m1.add(m3);
    console.assert(false, "Should have thrown error for shape mismatch in addition");
  } catch (e) {
    console.assert(e.message === "Matrix shapes must match for addition", "Should throw correct error for addition shape mismatch");
  }

  // Test shape mismatch error for subtraction
  try {
    m1.sub(m3);
    console.assert(false, "Should have thrown error for shape mismatch in subtraction");
  } catch (e) {
    console.assert(e.message === "Matrix shapes must match for subtraction", "Should throw correct error for subtraction shape mismatch");
  }

  // Test non-Matrix operand error
  try {
    m1.add("not a matrix");
    console.assert(false, "Should have thrown error for non-Matrix operand in addition");
